.catalog-shell,.catalog-inner,.catalog-section,.catalog-cart-page{--catalog-green:#173d37;--catalog-gold:#dda149;background:#f7f8f9;color:#202b30;padding:40px 0 64px;line-height:1.7;font-family:"Segoe UI",Arial,sans-serif}.catalog-shell *, .catalog-inner *{box-sizing:border-box}.catalog-shell-wrap,.catalog-container{width:min(1180px,calc(100% - 40px));margin:auto}.catalog-shell a{color:inherit;text-decoration:none}.catalog-shell nav{font-size:13px;margin-bottom:28px}.catalog-product{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:42px}.catalog-product>*{min-width:0}.catalog-product img{display:block;width:100%;height:auto;max-height:520px;object-fit:contain;background:white;border-radius:14px;margin-bottom:16px}.catalog-product h1{font-size:clamp(28px,3vw,42px);line-height:1.3;margin:0 0 20px}.catalog-price{font-size:28px;color:#173d37}.catalog-product form{display:flex;gap:16px;align-items:end;flex-wrap:wrap;margin:24px 0}.catalog-product input{display:block;padding:12px;width:90px;border:1px solid #b9c8c1;border-radius:6px}.catalog-product button,.catalog-more,.catalog-book{display:inline-block;padding:12px 22px;border:0;border-radius:6px;background:#173d37;color:white;font:inherit;cursor:pointer}.catalog-copy{overflow-wrap:anywhere;overflow:auto}.catalog-copy img,.catalog-copy iframe{max-width:100%}.catalog-inner-hero{padding:24px 0}.catalog-section h1{font-size:32px}.catalog-checkout{color:#202b30}.catalog-cart-page{--catalog-green:#173d37;--catalog-gold:#dda149}.catalog-shell button:focus-visible,.catalog-shell a:focus-visible{outline:3px solid #dda149;outline-offset:3px}@media(max-width:760px){.catalog-product{grid-template-columns:1fr;gap:24px}.catalog-shell-wrap,.catalog-container{width:calc(100% - 32px)}}
